/* رحلة الفصل إلى السماء — منطق اللعبة */

/* الصور المضمّنة (المنطاد والمنظر الطبيعي) */
const ASSETS = {
  balloon: 'data:image/webp;base64,',
  land: 'data:image/webp;base64,'
};
document.querySelectorAll('img[data-asset]').forEach(img => { img.src = ASSETS[img.dataset.asset]; });

/* ---------------- المحتوى القرآني ----------------
   السورة الافتراضية: سورة الملك برواية حفص بالرسم العثماني، مطابقة حرفًا وتشكيلًا لنص مجمع الملك فهد (الإصدار ١٣).
   يمكن للمعلمة لصق نص أي سورة من «تغيير السورة»، فتُقسَّم آياتها تلقائيًا (آية في كل سحابة). */
const VERSES = [
 "تَبَـٰرَكَ ٱلَّذِی بِیَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ",
 "ٱلَّذِی خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَیَوٰةَ لِیَبۡلُوَكُمۡ أَیُّكُمۡ أَحۡسَنُ عَمَلࣰاۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡغَفُورُ",
 "ٱلَّذِی خَلَقَ سَبۡعَ سَمَـٰوَ ٰ⁠تࣲ طِبَاقࣰاۖ مَّا تَرَىٰ فِی خَلۡقِ ٱلرَّحۡمَـٰنِ مِن تَفَـٰوُتࣲۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورࣲ",
 "ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَیۡنِ یَنقَلِبۡ إِلَیۡكَ ٱلۡبَصَرُ خَاسِئࣰا وَهُوَ حَسِیرࣱ",
 "وَلَقَدۡ زَیَّنَّا ٱلسَّمَاۤءَ ٱلدُّنۡیَا بِمَصَـٰبِیحَ وَجَعَلۡنَـٰهَا رُجُومࣰا لِّلشَّیَـٰطِینِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِیرِ",
 "وَلِلَّذِینَ كَفَرُوا۟ بِرَبِّهِمۡ عَذَابُ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمَصِیرُ",
 "إِذَاۤ أُلۡقُوا۟ فِیهَا سَمِعُوا۟ لَهَا شَهِیقࣰا وَهِیَ تَفُورُ",
 "تَكَادُ تَمَیَّزُ مِنَ ٱلۡغَیۡظِۖ كُلَّمَاۤ أُلۡقِیَ فِیهَا فَوۡجࣱ سَأَلَهُمۡ خَزَنَتُهَاۤ أَلَمۡ یَأۡتِكُمۡ نَذِیرࣱ",
 "قَالُوا۟ بَلَىٰ قَدۡ جَاۤءَنَا نَذِیرࣱ فَكَذَّبۡنَا وَقُلۡنَا مَا نَزَّلَ ٱللَّهُ مِن شَیۡءٍ إِنۡ أَنتُمۡ إِلَّا فِی ضَلَـٰلࣲ كَبِیرࣲ",
 "وَقَالُوا۟ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِیۤ أَصۡحَـٰبِ ٱلسَّعِیرِ",
 "فَٱعۡتَرَفُوا۟ بِذَنۢبِهِمۡ فَسُحۡقࣰا لِّأَصۡحَـٰبِ ٱلسَّعِیرِ",
 "إِنَّ ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُم بِٱلۡغَیۡبِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِیرࣱ",
 "وَأَسِرُّوا۟ قَوۡلَكُمۡ أَوِ ٱجۡهَرُوا۟ بِهِۦۤۖ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ",
 "أَلَا یَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِیفُ ٱلۡخَبِیرُ",
 "هُوَ ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولࣰا فَٱمۡشُوا۟ فِی مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزۡقِهِۦۖ وَإِلَیۡهِ ٱلنُّشُورُ",
 "ءَأَمِنتُم مَّن فِی ٱلسَّمَاۤءِ أَن یَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِیَ تَمُورُ",
 "أَمۡ أَمِنتُم مَّن فِی ٱلسَّمَاۤءِ أَن یُرۡسِلَ عَلَیۡكُمۡ حَاصِبࣰاۖ فَسَتَعۡلَمُونَ كَیۡفَ نَذِیرِ",
 "وَلَقَدۡ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ فَكَیۡفَ كَانَ نَكِیرِ",
 "أَوَلَمۡ یَرَوۡا۟ إِلَى ٱلطَّیۡرِ فَوۡقَهُمۡ صَـٰۤفَّـٰتࣲ وَیَقۡبِضۡنَۚ مَا یُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَـٰنُۚ إِنَّهُۥ بِكُلِّ شَیۡءِۭ بَصِیرٌ",
 "أَمَّنۡ هَـٰذَا ٱلَّذِی هُوَ جُندࣱ لَّكُمۡ یَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَـٰنِۚ إِنِ ٱلۡكَـٰفِرُونَ إِلَّا فِی غُرُورٍ",
 "أَمَّنۡ هَـٰذَا ٱلَّذِی یَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّوا۟ فِی عُتُوࣲّ وَنُفُورٍ",
 "أَفَمَن یَمۡشِی مُكِبًّا عَلَىٰ وَجۡهِهِۦۤ أَهۡدَىٰۤ أَمَّن یَمۡشِی سَوِیًّا عَلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ",
 "قُلۡ هُوَ ٱلَّذِیۤ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِیلࣰا مَّا تَشۡكُرُونَ",
 "قُلۡ هُوَ ٱلَّذِی ذَرَأَكُمۡ فِی ٱلۡأَرۡضِ وَإِلَیۡهِ تُحۡشَرُونَ",
 "وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ",
 "قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَاۤ أَنَا۠ نَذِیرࣱ مُّبِینࣱ",
 "فَلَمَّا رَأَوۡهُ زُلۡفَةࣰ سِیۤـَٔتۡ وُجُوهُ ٱلَّذِینَ كَفَرُوا۟ وَقِیلَ هَـٰذَا ٱلَّذِی كُنتُم بِهِۦ تَدَّعُونَ",
 "قُلۡ أَرَءَیۡتُمۡ إِنۡ أَهۡلَكَنِیَ ٱللَّهُ وَمَن مَّعِیَ أَوۡ رَحِمَنَا فَمَن یُجِیرُ ٱلۡكَـٰفِرِینَ مِنۡ عَذَابٍ أَلِیمࣲ",
 "قُلۡ هُوَ ٱلرَّحۡمَـٰنُ ءَامَنَّا بِهِۦ وَعَلَیۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِی ضَلَـٰلࣲ مُّبِینࣲ",
 "قُلۡ أَرَءَیۡتُمۡ إِنۡ أَصۡبَحَ مَاۤؤُكُمۡ غَوۡرࣰا فَمَن یَأۡتِیكُم بِمَاۤءࣲ مَّعِینِۭ"
];
const LEVELS = [
  { name: 'المستوى الأول',  place: 'على المرج الأخضر' },
  { name: 'المستوى الثاني', place: 'عند سفح الجبل' },
  { name: 'المستوى الثالث', place: 'في منتصف الجبل' },
  { name: 'المستوى الرابع', place: 'فوق قمة الجبل' },
  { name: 'المستوى الخامس', place: 'تحت السحاب' },
  { name: 'المستوى السادس', place: 'فوق السحاب' },
];

(() => {
'use strict';
const REPS = 3, KEY = 'classSkyOneScreen.v1', SKEY = 'classSkySurah.v1';   // ثلاث ترديدات لكل آية
const AR = n => String(n).replace(/\d/g, d => '٠١٢٣٤٥٦٧٨٩'[d]);
const $ = id => document.getElementById(id);

/* ---------- السورة الحالية (افتراضيًا الملك، أو ما تلصقه المعلمة) ---------- */
const DEFAULT_SUR = { name: 'الملك', verses: VERSES.slice(), nums: VERSES.map((_, i) => i + 1) };
let SUR = DEFAULT_SUR;
try {
  const d = JSON.parse(localStorage.getItem(SKEY) || 'null');
  if (d && typeof d.name === 'string' && Array.isArray(d.verses) && d.verses.length > 0 && d.verses.every(v => typeof v === 'string' && v.trim())
      && Array.isArray(d.nums) && d.nums.length === d.verses.length) SUR = d;
} catch (e) {}
let N = SUR.verses.length;
const surId = sr => { let h = 7; const t = sr.name + '|' + sr.verses.join('|'); for (let i = 0; i < t.length; i++) h = (h * 31 + t.charCodeAt(i)) | 0; return h; };
const STAGES = () => Math.min(6, N);                     // ست مراحل للرحلة (أو أقل لسورة قصيرة جدًا)
const lvOf = i => Math.min(STAGES() - 1, Math.floor(i * STAGES() / N));
const surName = () => 'سورة ' + SUR.name;
const ayat = n => n === 1 ? 'آية واحدة' : n === 2 ? 'آيتان' : `${AR(n)} ${n <= 10 ? 'آيات' : 'آية'}`;   // صيغة العدد الصحيحة
const SPRITE_AR = 653 / 1074;

/* ---------- state ---------- */
const fresh = () => ({ v: 1, sid: surId(SUR), name: '', i: 0, reps: 0, done: Array(N).fill(0), started: false, launched: false, finished: false, sound: true, peak: 0 });
let S = fresh();
try {
  const d = JSON.parse(localStorage.getItem(KEY) || 'null');
  const sameSur = d && (d.sid === surId(SUR) || (d.sid === undefined && SUR === DEFAULT_SUR));   // التقدّم يخص السورة الحالية فقط
  if (d && sameSur && d.v === 1 && typeof d.name === 'string' && Number.isInteger(d.i) && d.i >= 0 && d.i < N && Number.isInteger(d.reps) && d.reps >= 0 && d.reps <= 5 && Array.isArray(d.done) && d.done.length === N)
    S = { ...fresh(), ...d, sid: surId(SUR), done: d.done.map(x => (x ? 1 : 0)) };
    if (S.reps >= REPS) S.reps = REPS - 1;   // حفظ قديم (كان ٥ ترديدات)
    if (typeof d.launched !== 'boolean') S.launched = d.i > 0 || d.reps > 0 || !!d.finished;
    if (typeof d.peak !== 'number' || !(d.peak >= 0) || d.peak > N) S.peak = d.finished ? N : d.i;
} catch (e) {}
const save = () => { try { localStorage.setItem(KEY, JSON.stringify(S)); } catch (e) {} };

/* ---------- sound ---------- */
let ac;
function tone(fs, gap = .12, dur = .5, vol = .07) {
  if (!S.sound) return;
  try {
    ac = ac || new (window.AudioContext || window.webkitAudioContext)(); const t = ac.currentTime;
    fs.forEach((f, k) => { const o = ac.createOscillator(), g = ac.createGain(); o.type = 'sine'; o.frequency.value = f;
      g.gain.setValueAtTime(0, t + k * gap); g.gain.linearRampToValueAtTime(vol, t + k * gap + .02); g.gain.exponentialRampToValueAtTime(.0001, t + k * gap + dur);
      o.connect(g).connect(ac.destination); o.start(t + k * gap); o.stop(t + k * gap + dur + .05); });
  } catch (e) {}
}
function soundIcon() {
  $('soundBtn').innerHTML = S.sound
    ? '<svg viewBox="0 0 24 24"><path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M16 8.5a5 5 0 0 1 0 7M18.5 6a8.5 8.5 0 0 1 0 12" stroke="currentColor" stroke-width="2" fill="none"/></svg>'
    : '<svg viewBox="0 0 24 24"><path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M16 9l6 6M22 9l-6 6" stroke="currentColor" stroke-width="2"/></svg>';
  $('soundBtn').style.color = 'var(--text)';
  $('soundBtn').setAttribute('aria-label', S.sound ? 'إيقاف الصوت' : 'تشغيل الصوت');
}

/* ---------- geometry (recomputed on resize) ---------- */
let G = {};
let transit = false;
let inGame = false;   // في شاشة البداية لا تظهر أي سحابة آية
function geometry() {
  const W = innerWidth, H = innerHeight, land = W > H && W >= 700;
  const hudH = ($('hud').offsetHeight || 64) + 16, ctlH = ($('controls').offsetHeight || 150) + 16;
  const bh = land ? Math.min(H * .46, 390) : Math.max(130, Math.min(H * .2, 200));
  G = { W, H, land, hudH, ctlH, bh, bw: bh * SPRITE_AR };
  G.step = H * .6;                               // المسافة بين محطة آية والتي تليها (أكبر دائمًا من صعود المنطاد على الشاشة)
  G.want = ctlH;                                 // أسفل المنطاد فوق لوحة الترديد مباشرة
  G.base = G.want;                               // السلة على العشب فوق لوحة الترديد مباشرة
  G.lift = H * (land ? .07 : .04);              // ارتفاع الإقلاع الأول عن الأرض
  G.top = altOf(30); G.worldH = G.top + H * 1.3;
}
// ارتفاع محطة الآية i
const altOf = i => G.base + G.lift + i * G.step;
let intro = null;   // 'zoom' أثناء ابتعاد الكاميرا والمنطاد ما زال على الأرض
const grounded = () => !inGame || !S.launched || intro === 'zoom';
/* نموذج الحركة:
   - أثناء ترديد الآية: الكاميرا والمنظر والسحابة ثابتون، والمنطاد نفسه يصعد على الشاشة خطوة مع كل ترديد
     حتى يصل أسفل سحابة الآية مباشرة (دون أن يغطيها) عند الترديد الخامس.
   - بعد إتمام الآية: يستمر المنطاد في الصعود والكاميرا تصعد معه إلى المحطة التالية، وتظهر الآية الجديدة في نفس المكان.
   - التقدّم يُحفظ كرقم واحد (محطة + كسر) ولا ينقص أبدًا. */
const stationAlt = u => u >= N ? G.top + G.step * .3 : altOf(u);
const curNum = () => S.finished ? N : S.i + Math.min(S.reps, REPS) / REPS * .999;
function eff() {
  const u = Math.max(curNum(), S.peak || 0);
  if (u >= N) return { st: N, fr: .55 };
  const st = Math.floor(u); return { st, fr: Math.min(1, (u - st) / .999) };
}
const altP = () => grounded() ? G.base : stationAlt(eff().st);   // ارتفاع الكاميرا/المحطة الحالية
// الكاميرا تتحرك مع المنطاد بنفس التوقيت تمامًا، فلا يبدو أبدًا أنه ينزل على الشاشة
const camOf = alt => Math.max(0, Math.min(G.worldH - G.H, alt - G.want - G.lift));
const balloonX = () => G.W / 2;   // المنطاد دائمًا في منتصف الشاشة أفقيًا

/* ---------- scenery ---------- */
function scenery() {
  // المنظر البانورامي ثابت خلف العالم، وتتحكم فيه الكاميرا حسب الارتفاع (camera)
  const { W, H } = G;
  $('world').style.height = G.worldH + 'px';
  $('land').style.width = LAND_W + 'px'; $('land').style.height = LAND_H + 'px';
  // طبقة السحاب الكثيفة: يدخلها المنطاد ثم تصبح بحرًا من السحاب تحته
  const D = H * 1.6; G.deckH = D;
  let r = 9; const rnd = () => (r = (r * 16807) % 2147483647) / 2147483647;
  const puff = (x, y, k, f) => `<g fill="${f}"><ellipse cx="${x}" cy="${y + 18 * k}" rx="${110 * k}" ry="${30 * k}"/><circle cx="${x - 52 * k}" cy="${y + 2 * k}" r="${40 * k}"/><circle cx="${x}" cy="${y - 18 * k}" r="${54 * k}"/><circle cx="${x + 54 * k}" cy="${y + 4 * k}" r="${38 * k}"/></g>`;
  const k0 = Math.max(.7, W / 900);
  let p = `<defs><linearGradient id="dg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFFFFF"/><stop offset=".45" stop-color="#F4F8FC" stop-opacity=".9"/><stop offset="1" stop-color="#DCE9F5" stop-opacity=".72"/></linearGradient></defs>`;
  p += `<rect x="0" y="${D * .16}" width="${W}" height="${D * .84}" fill="url(#dg)"/>`;
  for (let row = 0; row < 7; row++) {
    const y = D * (.05 + row * .05), n = Math.ceil(W / (150 * k0)) + 2;
    for (let i = 0; i < n; i++) p += puff((i + (row % 2) * .5 - .5) * W / (n - 2) + (rnd() - .5) * 40, y + (rnd() - .5) * 26, k0 * (.8 + rnd() * .7), row < 2 ? '#FFFFFF' : (row % 2 ? '#F7FAFD' : '#FFFFFF'));
  }
  for (let i = 0; i < 26; i++) p += puff(rnd() * W, D * (.4 + rnd() * .55), k0 * (.6 + rnd() * .8), rnd() > .5 ? '#EAF2FA' : '#FFFFFF');
  $('deck').style.height = D + 'px';
  $('deck').innerHTML = `<svg viewBox="0 0 ${W} ${D}" preserveAspectRatio="none">${p}</svg>`;
  // سحب خفيفة ثابتة في العالم بين المحطات، على الأطراف بعيدًا عن الآية
  let wh = '';
  for (let k = 0; k <= N; k++) for (let j = 0; j < 3; j++) {
    const side = (k + j) % 2, ww = W * (G.land ? .2 : .42) * (.8 + rnd() * .5), hh = ww * .32;
    const x = side ? W - ww * (.55 + rnd() * .2) : -ww * (.45 - rnd() * .2);
    const a = altOf(k) + G.step * (.12 + j * .3 + rnd() * .1) + G.bh * .5;
    wh += `<div class="wisp" style="left:${x}px;bottom:${a}px;width:${ww}px;height:${hh}px;opacity:${.55 + rnd() * .35}"></div>`;
  }
  $('wisps').innerHTML = '';   // لا سحب إضافية: المنظر من الصورة فقط
}

/* ---------- station clouds ---------- */
const st = [];
function buildStations() {
  for (let i = 0; i < N; i++) {
    const c = document.createElement('div'); c.className = 'st far';
    c.innerHTML = `<div class="tag">${surName()}، الآية ${AR(SUR.nums[i])}</div><p class="ayah"><span></span><span class="num"> \u06DD${AR(SUR.nums[i])}</span></p><div class="badge">${AR(SUR.nums[i])}</div>`;
    c.querySelector('.ayah span').textContent = SUR.verses[i];
    $('clouds').append(c); st.push(c);
  }
}
function cloudBox(i) {
  // سحابة الآية ثابتة على الشاشة: في الأعلى على الجوال، وعلى الجانب في الشاشات العريضة
  const { W, land } = G;
  if (land) { const w = Math.min(W * .54, 820); return { w, left: W * .67 - w / 2, font: Math.max(26, Math.min(W * .032, 62)) }; }
  const w = Math.min(W - 16, 640);
  return { w, left: (W - w) / 2, font: Math.max(20, Math.min(W * .062, 36)) };
}
function layoutStations() {
  const { H, hudH, ctlH, land } = G;
  for (let i = 0; i < N; i++) {
    const c = st[i], b = cloudBox(i);
    c.style.width = b.w + 'px'; c.style.left = b.left + 'px'; c.style.transform = 'none';
    c.dataset.font = b.font;                         // يُضبط حجم الخط عند ظهور السحابة فقط (أسرع للسور الطويلة)
  }
  stationStates();
}
// يختار مكان سحابة الآية (أعلى/أسفل على الجوال، يمين/يسار على الشاشة العريضة) بعيدًا عن مسار المنطاد في هذه الآية
// يضبط خط الآية ليناسب المساحة (بحث ثنائي)؛ الآيات الطويلة جدًا يمكن تمريرها داخل السحابة
function fitCloud(c, maxC, f0) {
  const a = c.querySelector('.ayah'); c.style.maxHeight = ''; c.style.overflowY = '';
  let lo = 16, hi = f0;
  a.style.fontSize = hi + 'px';
  if (c.offsetHeight > maxC) {
    for (let k = 0; k < 7; k++) { const m = (lo + hi) / 2; a.style.fontSize = m + 'px'; if (c.offsetHeight > maxC) hi = m; else lo = m; }
    a.style.fontSize = Math.floor(lo) + 'px';
    if (c.offsetHeight > maxC) { c.style.maxHeight = maxC + 'px'; c.style.overflowY = 'auto'; c.style.pointerEvents = 'auto'; }
  }
}
function placeCloud(i) {
  const c = st[i], { W, H, hudH, ctlH, land, bw, bh } = G;
  if (!land) fitCloud(c, (H - hudH - ctlH) * .46, +c.dataset.font || 30);
  const a = balloonScreen(false, i, 0), z = balloonScreen(false, i, 1);
  const bTop = Math.min(a.Y - bh * a.k, z.Y - bh * z.k), bBot = Math.max(a.Y, z.Y);
  const bL = Math.min(a.X, z.X) - bw * a.k / 2, bR = Math.max(a.X, z.X) + bw * a.k / 2;
  const ch = c.offsetHeight, cw = c.offsetWidth;
  if (land) {
    // الجهة الأوسع بعيدًا عن المنطاد، وعرض السحابة على قدر المساحة الفارغة
    const freeL = bL - 16, freeR = W - bR - 16, onRight = freeR >= freeL;
    const w = clamp(Math.min(W * .54, (onRight ? freeR : freeL) - 8), 320, W * .54);
    c.style.width = w + 'px';
    fitCloud(c, H - hudH - ctlH - 10, Math.max(26, Math.min(W * .032, 62)));
    const top = hudH + Math.max(0, (H - hudH - ctlH - c.offsetHeight) / 2);
    c.style.left = (onRight ? Math.max(bR + 16, W - w - 16) : 16) + 'px'; c.style.top = top + 'px';
  } else {
    const topT = hudH - 6, botT = H - ctlH - ch - 4;
    const ovT = Math.max(0, topT + ch + 8 - bTop), ovB = Math.max(0, bBot - botT + 8);
    c.style.top = (ovT <= ovB ? topT : botT) + 'px';
  }
}
function stationStates() {
  for (let i = 0; i < N; i++) {
    const c = st[i], active = !transit && inGame && S.launched && !intro && i === S.i && S.started && !S.finished;
    c.classList.toggle('active', active); c.classList.toggle('done', !!S.done[i]);
    if (active) placeCloud(i);
    c.classList.toggle('far', !active);                // لا تظهر إلا سحابة الآية الحالية، ثابتة في مكانها
  }
}

/* ---------- balloon + camera ---------- */
function placeBalloon(alt, hop) {
  const b = $('balloon'), g = grounded(), e = eff();
  const p = g ? balloonScreen(true, 0, 0) : balloonScreen(false, e.st, e.fr);   // يصعد على الصورة نصيبه المحسوب مع كل ترديد
  b.classList.toggle('hop', !!hop);
  Object.assign(b.style, { width: G.bw + 'px', height: G.bh + 'px', left: '0px',
    transform: `translate3d(${(p.X - G.bw / 2).toFixed(1)}px, ${(p.Y - G.H).toFixed(1)}px, 0) scale(${p.k.toFixed(4)})` });
  b.classList.toggle('grounded', g);                 // ثابت تمامًا على الأرض قبل بدء الرحلة
  const sh = $('shadow'), sw = G.bw * .62;
  Object.assign(sh.style, { width: sw + 'px', height: sw * .18 + 'px', left: balloonX() - sw / 2 + 'px', bottom: G.base - sw * .07 + 'px', opacity: g ? 1 : 0 });
}
const LAND_W = 1671, LAND_H = 941;
// مسار الجولة فوق الصورة: [التقدّم (آية), x, y (نسبة من الصورة), ay موضعها على الشاشة في النهاية]
const TOUR = [   // [الآية, x في الصورة] — المسار الأفقي فوق الأماكن من الأرض إلى الشمس
  [0, .2333, 0], [4, .33, 0], [8, .22, 0], [12, .42, 0], [16, .66, 0], [20, .82, 0], [24, .62, 0], [27, .76, 0], [30, .88, 0]
];
function landGeo() {
  // البداية: تكبير على المنطاد والخضرة. النهاية: الصورة كلها ظاهرة (على الجوال: كامل ارتفاعها)
  const { W, H } = G;
  const s0 = 3.0 * H / LAND_H;                               // تكبير أكبر في البداية = مسافة صعود أوضح مع كل ترديد
  const sEnd = G.land ? Math.min(W / LAND_W, H / LAND_H) : Math.max(W / LAND_W, H / LAND_H);
  const bhImg = G.bh / s0, liftImg = G.lift / s0;            // حجم المنطاد ثابت بوحدات الصورة
  const iy0 = GROUND.y - liftImg / LAND_H;                    // بعد الإقلاع مباشرة
  const iy1 = .10 + bhImg / LAND_H;                           // النهاية: المنطاد في أعلى السماء بجوار الشمس
  return { s0, sEnd, iy: u => lerp(iy0, iy1, clamp(u, 0, 1)) };
}
// أسفل السلة على الشاشة: المنطاد في منتصف الشاشة
const basketY = () => G.land ? G.H * .52 + G.bh / 2 : G.H * .56 + G.bh / 2;
// الكاميرا عند تقدّم p (آيات + كسر الترديد): مقياس يصغر تدريجيًا، والصورة تنزل تحت المنطاد
function camAt(p, groundMode) {
  const { W, H } = G, L = landGeo(), u = clamp(p / N, 0, 1);
  const s = L.s0 * Math.pow(L.sEnd / L.s0, u);
  const w = LAND_W * s, h = LAND_H * s;
  const iy = groundMode ? GROUND.y : L.iy(u);
  // على الأرض: السلة فوق لوحة الترديد على الخضرة، ثم يرتفع المنطاد لمنتصف الشاشة خلال الآيتين الأوليين
  const TY = groundMode ? G.H - G.want : lerp(G.H - G.want - G.lift, basketY(), smooth(clamp(p / 2, 0, 1)));
  const ix = groundMode ? GROUND.x : colAt(p);
  let x = W / 2 - ix * w, y = TY - iy * h;
  x = w >= W ? clamp(x, W - w, 0) : (W - w) / 2;
  y = h >= H ? clamp(y, H - h, 0) : (H - h) / 2;              // عندما تظهر الصورة كلها يصعد المنطاد على الشاشة
  return { s, w, h, x, y, k: s / L.s0 };
}
// موضع المنطاد على الشاشة = نقطته في الصورة (عمود رأسي ثابت، يتحرك لأعلى فقط)
function balloonScreen(groundMode, kSt, frac) {
  const p = groundMode ? 0 : kSt + frac, c = camAt(p, groundMode), L = landGeo();
  const iy = groundMode ? GROUND.y : L.iy(p / N);
  return { X: c.x + (groundMode ? GROUND.x : colAt(p)) * c.w, Y: c.y + iy * c.h, k: c.k, cam: c };
}
// وضع الكاميرا عند محطة الآية k: مقياس (يصغر تدريجيًا) وموضع الصورة
// موضع المنطاد على الشاشة: نقطته الحقيقية في الصورة
function tourAt(p) {
  // منحنى ناعم (Catmull-Rom) يمر بكل الأماكن بالترتيب
  let k = 0; while (k < TOUR.length - 2 && p > TOUR[k + 1][0]) k++;
  const P = i => TOUR[Math.max(0, Math.min(TOUR.length - 1, i))];
  const a = P(k - 1), b = P(k), c = P(k + 1), d = P(k + 2);
  const t = clamp((p - b[0]) / (c[0] - b[0]), 0, 1), t2 = t * t, t3 = t2 * t;
  const cr = j => .5 * (2 * b[j] + (-a[j] + c[j]) * t + (2 * a[j] - 5 * b[j] + 4 * c[j] - d[j]) * t2 + (-a[j] + 3 * b[j] - 3 * c[j] + d[j]) * t3);
  return { x: clamp(cr(1), 0, 1), y: clamp(cr(2), 0, 1), ay: .24 };
}
// موضع المنطاد الأصلي في الصورة: نقطة ملامسة السلة للممر الترابي وارتفاع المنطاد (بالبكسل)
// خط الصعود: عمود رأسي في منتصف الصورة، يبدأ من الخضرة أسفلها
// نقطة البداية: السلة على العشب الأخضر بجوار الممر الترابي
const GROUND = { x: .30, y: .88 };
// العمود الذي يقع تحت المنطاد: يبدأ من العشب ثم ينتقل بهدوء إلى منتصف الصورة خلال الآيتين الأوليين
const colAt = p => lerp(GROUND.x, .5, smooth(clamp(p / 2, 0, 1)));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;
const smooth = t => t * t * (3 - 2 * t);
function camera(alt, hop) {
  $('land').classList.toggle('hop', !!hop);
  // ١) العالم (السحب والمنطاد) يتبع المنطاد
  const c = camOf(alt);
  $('world').style.transform = `translateY(${c}px)`;
  const { W, H } = G;
  // تكبير بسيط على المنطاد وهو على الأرض، ثم ابتعاد سينمائي هادئ عند بدء الرحلة
  const onGround = !inGame || !S.launched;
  const Z = onGround ? (G.land ? 1.12 : 1.3) : 1;
  const gp = balloonScreen(true, 0, 0);
  $('zoom').style.transformOrigin = `${gp.X}px ${gp.Y}px`;   // التكبير حول السلة على العشب
  $('zoom').style.transform = `scale(${Z})`;
  // ٢) الصورة: ثابتة أثناء ترديد الآية، وتبتعد الكاميرا خطوة مع كل آية جديدة
  const ef = eff(), cm = camAt(onGround ? 0 : ef.st + ef.fr, onGround);   // تتحرك مع كل ترديد
  $('turf').style.opacity = 0;
  $('land').style.transform = `translate(${cm.x}px, ${cm.y}px) scale(${cm.s})`;
}

/* ---------- labels + HUD ---------- */
function fitLabel() {
  const l = $('label'); l.textContent = S.name; l.classList.toggle('empty', !S.name); l.style.fontSize = '';
  if (!S.name) return; let fs = parseFloat(getComputedStyle(l).fontSize);
  while (l.scrollWidth > l.clientWidth + 1 && fs > 7) { fs--; l.style.fontSize = fs + 'px'; }
}
function hud() {
  const lv = LEVELS[lvOf(S.i)]; $('lvName').textContent = lv.name; $('lvPlace').textContent = lv.place;
  $('of').textContent = `الآية ${AR(S.i + 1)} من ${AR(N)}`;
  const p = S.finished ? 1 : Math.min(1, (S.i + S.reps / REPS) / N);
  $('mini').style.right = `calc(${p} * (100% - 30px))`;   // المنطاد الصغير يتقدم نحو الشمس
  [...$('bar').querySelectorAll('.s')].forEach((s, k) => { s.classList.toggle('d', !!S.done[k]); s.classList.toggle('n', k === S.i && !S.done[k]); });
  $('backBtn').disabled = busy || !S.launched || (!S.finished && S.i === 0 && S.reps === 0);
  $('controls').classList.toggle('ready', !S.launched);
  $('cnt').textContent = `التكرار ${AR(S.reps)} من ${AR(REPS)}`;
  [...$('stars').children].forEach((s, k) => s.classList.toggle('lit', k < S.reps));
  $('rep').disabled = busy || S.reps >= REPS || S.finished;
}
let tt; function toast(m, ms = 1900) { const t = $('toast'); t.textContent = m; t.classList.add('show'); clearTimeout(tt); tt = setTimeout(() => t.classList.remove('show'), ms); }
function sparks() {
  const r = st[S.i].getBoundingClientRect(), b = $('sparks'); b.innerHTML = '';
  for (let k = 0; k < 14; k++) { const s = document.createElement('i'), a = k / 14 * Math.PI * 2;
    s.style.left = r.left + r.width / 2 + 'px'; s.style.top = r.top + r.height / 2 + 'px';
    s.style.setProperty('--dx', Math.cos(a) * (140 + Math.random() * 100) + 'px'); s.style.setProperty('--dy', Math.sin(a) * (90 + Math.random() * 60) + 'px'); b.append(s); }
}

/* ---------- game flow ---------- */
let busy = false, cool = false;
function rep() {
  if (busy || cool || S.finished || S.reps >= REPS || !S.started || !S.launched) return;
  cool = true; setTimeout(() => (cool = false), 400);
  S.reps++; tone([784], 0, .35, .06);
  S.peak = Math.max(S.peak || 0, curNum());                 // التقدّم لا ينقص أبدًا
  placeBalloon(altP(), true);                               // المنطاد يصعد خطوة واضحة
  camera(altP(), true);                                     // الصورة تنزل وتبتعد قليلًا
  save(); hud();
  const star = $('stars').children[S.reps - 1]; star.classList.remove('lit'); void star.offsetWidth; star.classList.add('lit');
  if (S.reps === REPS) complete();
}
const dur = v => parseFloat(getComputedStyle(document.documentElement).getPropertyValue(v)) * 1000;
function complete() {
  busy = true; S.done[S.i] = 1; save(); hud();
  st[S.i].classList.add('glow'); sparks();
  const last = S.i === N - 1, lvEnd = !last && lvOf(S.i + 1) !== lvOf(S.i);
  if (last) { tone([523, 659, 784, 1047, 1319], .12, .8); toast(`أحسنتم! أتممتم ${surName()} كاملة`, 2400); }
  else if (lvEnd) { tone([523, 659, 784, 1047], .12, .7); toast(`أحسنتم! أتممتم ${LEVELS[lvOf(S.i)].name}، هيا نصعد إلى ${LEVELS[lvOf(S.i) + 1].name}`, 3600); }
  else { tone([659, 784, 988], .13, .6); toast('أحسنتم! لننتقل إلى الآية التالية'); }
  setTimeout(() => { st[S.i].classList.remove('glow'); ascend(last); }, 1300);
}
function ascend(last) {
  const from = S.i, to = last ? from : from + 1;
  transit = true; st[from].classList.add('done');
  S.finished = last;
  S.peak = Math.max(S.peak || 0, last ? N : to); save();   // المحطة التالية: تُحفظ ولا تنقص
  stationStates();                                    // الغيمة الحالية تختفي
  const alt = altP();
  setTimeout(() => { placeBalloon(alt); camera(alt); }, 150);
  setTimeout(() => {
    if (last) { save(); busy = false; transit = false; showEnd(); return; }
    S.i = to; S.reps = 0; save(); transit = false;      // التقدّم يُحفظ بعد وصول المنطاد
    stationStates(); hud();
    setTimeout(() => { busy = false; hud(); }, 450);    // الزر يعمل بعد ظهور الغيمة الجديدة كاملة
  }, 200 + Math.max(dur('--rise'), dur('--cam')));
}
function showEnd() {
  $('controls').hidden = true; $('end').hidden = false; hud();
  const n = S.done.reduce((a, b) => a + b, 0);
  $('sum').textContent = n === N ? `فصل «${S.name}» ردّد آيات ${surName()} كلها (${ayat(N)})، كل آية ثلاث مرات.` : `فصل «${S.name}» ردّد ${ayat(n)} من ${AR(N)}، كل آية ثلاث مرات.`;
  const f = $('fall'); f.innerHTML = '';
  if (!matchMedia('(prefers-reduced-motion: reduce)').matches) for (let k = 0; k < 24; k++) { const s = document.createElement('i'), z = 8 + Math.random() * 16;
    Object.assign(s.style, { left: Math.random() * 100 + '%', width: z + 'px', height: z + 'px', animationDuration: 6 + Math.random() * 7 + 's', animationDelay: -Math.random() * 12 + 's' }); f.append(s); }
}
function enterGame() {
  inGame = true;
  $('start').hidden = true; $('end').hidden = true; $('fall').innerHTML = '';
  $('hud').hidden = false; $('controls').hidden = S.finished;
  relayout(true);
  if (S.finished) { showEnd(); return; }
  if (S.reps >= REPS) { busy = true; hud(); setTimeout(() => { S.done[S.i] = 1; ascend(S.i === N - 1); }, 500); }
}
function showStart() {
  inGame = false;
  $('hud').hidden = true; $('controls').hidden = true; $('end').hidden = true; $('fall').innerHTML = '';
  $('start').hidden = false; $('cls').value = S.name; $('go').disabled = !S.name.trim();
  const r = $('resume'); r.hidden = !(S.started && !S.finished && S.name);
  r.textContent = `متابعة الرحلة (الآية ${AR(S.i + 1)})`;
  relayout(true);
}
function goBack() {
  if (busy || !inGame) return;
  if (S.finished) {                                   // من شاشة النهاية: نعود للآية الأخيرة
    S.finished = false; S.i = N - 1; S.done[N - 1] = 0;
    $('end').hidden = true; $('fall').innerHTML = ''; $('controls').hidden = false;
  } else if (S.i > 0) { S.i--; S.done[S.i] = 0; }
  else if (S.reps === 0) return;
  S.reps = 0; save();
  relayout(false);
  toast(`رجعنا إلى الآية ${AR(S.i + 1)}`, 1500);
}
function restart() { const name = S.name, sound = S.sound; S = fresh(); S.name = name; S.sound = sound; save(); showStart(); }

/* ---------- layout ---------- */
function relayout(instant) {
  const w = $('view'); if (instant) w.classList.add('instant');
  geometry(); scenery(); layoutStations();
  const alt = altP();
  placeBalloon(alt); camera(alt); fitLabel(); hud();
  if (instant) { void w.offsetWidth; requestAnimationFrame(() => w.classList.remove('instant')); }
}
let rt; addEventListener('resize', () => { clearTimeout(rt); rt = setTimeout(() => { if (!busy) relayout(true); }, 150); });

/* ---------- teacher settings ---------- */
function mrow(body, text, ...els) { const r = document.createElement('div'); r.className = 'mrow'; const p = document.createElement('p'); p.textContent = text; r.append(p);
  const l = document.createElement('div'); l.className = 'in'; l.append(...els); r.append(l); body.append(r); }
function mbtn(t, c, fn) { const b = document.createElement('button'); b.className = 'btn ' + c; b.textContent = t; b.onclick = fn; return b; }
function modal(build, wide) { document.querySelector('.mcard').classList.toggle('wide', !!wide); $('mt').textContent = wide ? 'اختيار السورة' : 'إعدادات المعلمة'; $('mbody').innerHTML = ''; build($('mbody')); $('modal').hidden = false; $('mclose').focus(); }
const closeM = () => ($('modal').hidden = true);
/* ---------- تقسيم نص أي سورة إلى آيات تلقائيًا ---------- */
const DIG = '0-9\u0660-\u0669\u06F0-\u06F9';
const toInt = t => parseInt(t.replace(/[\u0660-\u0669]/g, d => d.charCodeAt(0) - 0x660).replace(/[\u06F0-\u06F9]/g, d => d.charCodeAt(0) - 0x6F0), 10);
const skel = t => t.replace(/[\u0610-\u061A\u064B-\u065F\u0670\u06D6-\u06ED\u0640\u08D3-\u08FF\u200B-\u200F\u2060\s]/g, '')
  .replace(/[ٱأإآ]/g, 'ا').replace(/[یى]/g, 'ي');
const BASMALA = skel('بسم الله الرحمن الرحيم');
function stripBasmala(v) {
  if (!skel(v).startsWith(BASMALA)) return v;
  let acc = '', k = 0;
  for (; k < v.length && acc.length < BASMALA.length; k++) acc += skel(v[k]);
  while (k < v.length && (/\s/.test(v[k]) || skel(v[k]) === '')) k++;
  const rest = v.slice(k).trim();
  return rest || v;                       // لو البسملة هي الآية نفسها (الفاتحة) لا تُحذف
}
function parseSurah(text, dropBasmala) {
  // حذف سطر عنوان مثل «سورة الكهف» إن وُجد
  let t = text.replace(/\uFEFF/g, '').split(/\r?\n/).filter(l => !/^\s*سورة\s+\S+\s*$/.test(l)).join('\n');
  const re = new RegExp(`(?:\\u06DD\\s*)?[\\(\\[\\{\\uFD3E\\uFD3F]?\\s*([${DIG}]{1,3})\\s*[\\)\\]\\}\\uFD3E\\uFD3F]?`, 'g');
  const verses = [], nums = []; let last = 0, m, prev = 0, found = false;
  while ((m = re.exec(t))) {
    found = true;
    const seg = t.slice(last, m.index).replace(/\s+/g, ' ').trim();
    const n = toInt(m[1]);
    if (seg) { verses.push(seg); nums.push(n); prev = n; }
    last = m.index + m[0].length;
  }
  if (found) { const tail = t.slice(last).replace(/\s+/g, ' ').trim(); if (tail) { verses.push(tail); nums.push(prev + 1); } }
  else t.split(/\r?\n/).map(l => l.replace(/\s+/g, ' ').trim()).filter(Boolean).forEach((l, i) => { verses.push(l); nums.push(i + 1); });
  if (dropBasmala && verses.length > 1 && skel(verses[0]) === BASMALA && !found) { verses.shift(); nums.pop(); }   // بسملة في سطر مستقل
  else if (dropBasmala && verses.length) verses[0] = stripBasmala(verses[0]);
  const warn = nums.findIndex((n, i) => i > 0 && n !== nums[i - 1] + 1);
  return { verses, nums, warn };
}
function applySurah(sur) {
  SUR = sur; N = sur.verses.length;
  try { localStorage.setItem(SKEY, JSON.stringify(sur)); } catch (e) {}
  const name = S.name, sound = S.sound; S = fresh(); S.name = name; S.sound = sound; save();
  $('clouds').innerHTML = ''; st.length = 0; buildStations(); buildBar(); applyTexts();
  closeM(); showStart();
}
function surahEditor() {
  modal(body => {
    const nm = document.createElement('input'); nm.value = SUR.name; nm.maxLength = 30; nm.setAttribute('aria-label', 'اسم السورة'); nm.placeholder = 'مثال: الكهف';
    mrow(body, 'اسم السورة (بدون كلمة «سورة»)', nm);
    const r = document.createElement('div'); r.className = 'mrow';
    const p = document.createElement('p'); p.textContent = 'الصقي نص السورة هنا من مصدر موثوق (مثل مصحف المدينة). يمكن أن تكون الآيات بأرقامها مثل (١) أو ﴿١﴾، أو كل آية في سطر مستقل.';
    const ta = document.createElement('textarea'); ta.id = 'surText'; ta.setAttribute('aria-label', 'نص السورة'); ta.placeholder = 'الصقي نص السورة هنا…';
    const lb = document.createElement('label'); lb.className = 'chk'; const cb = document.createElement('input'); cb.type = 'checkbox'; cb.checked = true;
    lb.append(cb, document.createTextNode('حذف البسملة من بداية الآية الأولى'));
    const pv = document.createElement('div'); pv.id = 'surPrev'; pv.hidden = true;
    r.append(p, ta, lb, pv); body.append(r);
    let parsed = null;
    const use = mbtn('اعتماد السورة وبدء رحلة جديدة', 'gold', () => {
      if (!parsed || !parsed.verses.length) return;
      applySurah({ name: (nm.value.trim().replace(/^سورة\s+/, '') || 'السورة'), verses: parsed.verses, nums: parsed.nums });
    });
    use.disabled = true;
    const split = mbtn('تقسيم الآيات', 'soft', () => {
      parsed = parseSurah(ta.value, cb.checked); pv.hidden = false; pv.innerHTML = '';
      const head = document.createElement('div');
      if (!parsed.verses.length) { head.className = 'warn'; head.textContent = 'لم يتم العثور على آيات. تأكدي من لصق النص.'; pv.append(head); use.disabled = true; return; }
      head.className = 'ok'; head.textContent = `تم العثور على ${ayat(parsed.verses.length)}، كل آية ستكون في سحابة.`; pv.append(head);
      if (parsed.warn > 0) { const w = document.createElement('div'); w.className = 'warn'; w.textContent = `تنبيه: أرقام الآيات غير متتالية عند الآية ${AR(parsed.nums[parsed.warn])}. راجعي النص.`; pv.append(w); }
      const ol = document.createElement('ol');
      parsed.verses.forEach((v, i) => { const li = document.createElement('li'); li.value = parsed.nums[i]; li.textContent = v.length > 70 ? v.slice(0, 70) + '…' : v; ol.append(li); });
      pv.append(ol); use.disabled = false;
    });
    mrow(body, 'راجعي التقسيم قبل الاعتماد', split, use);
    if (SUR !== DEFAULT_SUR) mrow(body, 'الرجوع إلى السورة الأصلية', mbtn('سورة الملك', 'soft', () => applySurah(DEFAULT_SUR)));
  }, true);
}
function settings() {
  modal(body => {
    const inp = document.createElement('input'); inp.value = S.name; inp.maxLength = 20; inp.setAttribute('aria-label', 'اسم الفصل');
    mrow(body, 'اسم الفصل على المنطاد', inp, mbtn('حفظ', 'soft', () => { const v = inp.value.trim(); if (!v) return; S.name = v; save(); fitLabel(); closeM(); }));
    const u = mbtn('تراجع عن آخر ترديد', 'soft', () => { if (busy || S.reps < 1) return; S.reps--; save(); hud(); closeM(); }); u.disabled = busy || S.reps < 1;
    mrow(body, 'إذا ضُغط زر «تم الترديد» بالخطأ', u);
    const sel = document.createElement('select'); sel.setAttribute('aria-label', 'اختيار الآية');
    for (let k = 0; k < N; k++) { const o = document.createElement('option'); o.value = k; o.textContent = `الآية ${AR(SUR.nums[k])} (${LEVELS[lvOf(k)].name})`; o.selected = k === S.i; sel.append(o); }
    mrow(body, 'البدء من آية أخرى (يبدأ التكرار من الصفر)', sel, mbtn('انتقال', 'soft', () => { if (busy) return; S.i = +sel.value; S.reps = 0; S.finished = false; save(); closeM(); enterGame(); }));
    mrow(body, `السورة الحالية: ${surName()} (${ayat(N)})`, mbtn('تغيير السورة', 'soft', () => { if (!busy) surahEditor(); }));
    mrow(body, 'إعادة الرحلة من الآية الأولى', mbtn('إعادة الرحلة', 'danger', () => { if (busy) return;
      modal(b2 => mrow(b2, 'سيُمسح التقدّم ويعود المنطاد إلى المرج. هل أنتِ متأكدة؟', mbtn('نعم، أعيدي الرحلة', 'danger', () => { closeM(); restart(); }), mbtn('تراجع', 'soft', closeM))); }));
  });
}

/* ---------- wiring ---------- */
function buildBar() {
  const bar = $('bar'); bar.innerHTML = '';
  for (let g = 0; g < STAGES(); g++) {
    const d = document.createElement('div'); d.className = 'g'; if (N > 60) d.style.gap = '0';
    for (let k = 0; k < N; k++) if (lvOf(k) === g) { const s = document.createElement('div'); s.className = 's'; if (N > 60) s.style.borderRadius = '0'; d.append(s); }
    d.style.flex = String(d.childElementCount); bar.append(d);
  }
}
function applyTexts() {
  $('subT').textContent = `هيا نرتقي بآيات ${surName()}`;
  $('introT').textContent = `منطادنا ينتظرنا على الأرض. في كل سحابة آيةٌ من ${surName()}، نردّد الآية ثلاث مرات فيرتفع المنطاد إلى السحابة التالية، حتى نصل إلى الشمس فوق السحاب!`;
  $('endT').textContent = `وصلنا إلى نهاية رحلة ${surName()}!`;
  $('surNow').textContent = `السورة: ${surName()} (${ayat(N)})`;
  document.title = `رحلة الفصل إلى السماء: ${surName()}`;
}
buildBar(); applyTexts();
for (let k = 0; k < REPS; k++) $('stars').append(document.createElement('span'));
buildStations(); soundIcon();
$('cls').addEventListener('input', e => { const v = e.target.value.trim(); $('go').disabled = !v; S.name = v; fitLabel(); });
$('cls').addEventListener('keydown', e => { if (e.key === 'Enter' && !$('go').disabled) $('go').click(); });
$('go').onclick = () => { const v = $('cls').value.trim(); if (!v) return; const sound = S.sound; S = fresh(); S.name = v; S.sound = sound; S.started = true; save(); if (ac && ac.state === 'suspended') ac.resume(); enterGame(); };
$('resume').onclick = () => { save(); enterGame(); };
$('rep').onclick = rep;
$('soundBtn').onclick = () => { S.sound = !S.sound; save(); soundIcon(); };
$('setBtn').onclick = settings;
$('mclose').onclick = closeM;
$('modal').addEventListener('click', e => { if (e.target.id === 'modal') closeM(); });
addEventListener('keydown', e => { if (e.key === 'Escape') closeM(); });
$('again').onclick = restart;
$('surahBtn').onclick = () => { if (!busy) surahEditor(); };
$('backBtn').onclick = goBack;
$('homeBtn').onclick = () => { if (!busy) showStart(); };
$('launch').onclick = () => {                          // الآيات تظهر فقط بعد الضغط على «ابدأ»
  if (busy || S.launched) return;
  busy = true; S.launched = true; intro = 'zoom'; save();
  const v = $('view'); v.classList.add('cine');
  hud(); placeBalloon(altP()); camera(altP()); stationStates();   // الكاميرا تبتعد ببطء والمنطاد ثابت على العشب
  const cine = dur('--cine');
  setTimeout(() => {
    v.classList.remove('cine'); intro = 'lift';
    placeBalloon(altP()); camera(altP());                          // إقلاع هادئ عن الأرض
    setTimeout(() => {
      intro = null; stationStates();                               // تظهر سحابة الآية الأولى
      st[S.i].classList.add('glow'); setTimeout(() => st[S.i].classList.remove('glow'), 1100);
      tone([659, 784], .12, .5);
      setTimeout(() => { busy = false; hud(); }, 700);
    }, dur('--rise') + 100);
  }, cine + 100);
};
$('endX').onclick = () => { $('end').hidden = true; };   // إخفاء البطاقة ليظهر المنطاد عند الشمس؛ الإعادة متاحة من الإعدادات
const boot = () => { if (S.started && S.name) enterGame(); else showStart(); };
if (document.fonts) document.fonts.ready.then(boot); else boot();
})();
